-- Contrato privado: reservas, versiones, técnica, compartición y aislamiento.
begin;
set local statement_timeout='45s';
do $$
declare trainer uuid:=gen_random_uuid(); pupil uuid:=gen_random_uuid(); other uuid:=gen_random_uuid();
 rel uuid:=gen_random_uuid(); op uuid:=gen_random_uuid(); clip_op uuid:=gen_random_uuid(); demo uuid; clip uuid; claim uuid:=gen_random_uuid();
 exercise uuid; template uuid; scheduled uuid:=gen_random_uuid(); execution uuid; set_id uuid; video_id uuid:=gen_random_uuid();
 clip_video uuid:=gen_random_uuid(); draft jsonb; payload jsonb; url text; clip_url text; feedback uuid:=gen_random_uuid(); share_op uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email) values(trainer,trainer||'@private-videos.invalid'),(pupil,pupil||'@private-videos.invalid'),(other,other||'@private-videos.invalid');
 insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),trainer,'totp','verified',now(),now()),(gen_random_uuid(),other,'totp','verified',now(),now());
 insert into public.admin_permissions(user_id) values(trainer),(other);
 insert into public.trainer_access(trainer_id,enabled,client_limit,last_reason) values(trainer,true,1,'Vídeo privado'),(other,true,1,'Aislamiento');
 insert into public.trainer_client_relations(id,trainer_id,client_id,accepted_at) values(rel,trainer,pupil,now());
 perform set_config('request.jwt.claim.sub',trainer::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 demo:=public.reserve_exercise_video_upload('trainer_exercise',op,42,'fixture.b-cdn.net',20971521);
 if public.reserve_exercise_video_upload('trainer_exercise',op,42,'fixture.b-cdn.net',20971521)<>demo then raise exception 'Reserva duplicada'; end if;
 begin perform public.reserve_exercise_video_upload('trainer_exercise',op,42,'fixture.b-cdn.net',42); raise exception 'Cambia payload'; exception when invalid_parameter_value then null; end;
 begin perform public.reserve_exercise_video_upload('official',gen_random_uuid(),42,'fixture.b-cdn.net',20971521); raise exception 'Amplía vídeo oficial'; exception when insufficient_privilege then null; end;
 begin perform public.claim_exercise_video_creation(demo,claim); raise exception 'Cliente reclama proveedor'; exception when insufficient_privilege then null; end;
 if (public.get_exercise_video_asset(demo)->>'duration_limit')::int<>180 then raise exception 'Sin límites privados'; end if;
 if (public.get_exercise_video_asset(demo)->>'reserved_bytes')::bigint<>104857600 then raise exception 'Confía en tamaño declarado'; end if;
 if jsonb_array_length(public.list_trainer_exercise_videos())<>1 then raise exception 'Pierde reserva recuperable'; end if;
 if not exists(select 1 from jsonb_array_elements(public.get_trainer_video_usage()) x where x->>'scope'='trainer_exercise' and (x->>'asset_used')::int=1 and (x->>'bytes_reserved')::bigint=104857600) then raise exception 'Contabilidad duplicada'; end if;
 reset role;
 if public.claim_exercise_video_creation(demo,claim)->>'state'<>'claimed' then raise exception 'No reclama'; end if;
 if public.claim_exercise_video_creation(demo,gen_random_uuid())->>'state'<>'creating' then raise exception 'Duplica creación'; end if;
 perform public.mark_exercise_video_creation_uncertain(demo,claim);
 if public.claim_exercise_video_creation(demo,gen_random_uuid())->>'state'<>'uncertain' then raise exception 'Repite creación incierta'; end if;
 perform public.complete_exercise_video_creation(demo,null,video_id,true);
 url:='https://fixture.b-cdn.net/'||video_id||'/play_720p.mp4';
 update public.exercise_video_assets set status='ready',duration_seconds=120,playback_bytes=6291456,provider_storage_bytes=10000000 where id=demo;
 begin update public.exercise_video_assets set status='processing' where id=demo; raise exception 'Retrocede estado final'; exception when invalid_parameter_value then null; end;
 set local role authenticated;
 draft:=jsonb_build_object('name','Vídeo profesional','description','Técnica propia','video_url',url,'muscle_groups',jsonb_build_array('espalda'),'equipment',jsonb_build_array('barra'),'difficulty','intermedio','exercise_type','repeticiones');
 exercise:=public.save_trainer_exercise(gen_random_uuid(),draft);
 payload:=jsonb_build_object('name','Sesión con vídeo propio','blocks',jsonb_build_array(jsonb_build_object('name','Fuerza','format','straight_sets','rounds',1,'rest_after_seconds',0,'exercises',jsonb_build_array(jsonb_build_object('exercise_id',exercise,'sets',jsonb_build_array(jsonb_build_object('target_reps',8,'rest_after_seconds',60)))))));
 template:=public.save_trainer_workout(gen_random_uuid(),payload);
 perform public.assign_trainer_workout(scheduled,rel,template,current_date,null);
 perform set_config('request.jwt.claim.sub',other::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other,'role','authenticated','aal','aal2')::text,true);
 if public.can_read_exercise_video(url) or public.authorize_exercise_video_asset(demo,'status') or public.authorize_exercise_video_asset(demo,'thumbnail') then raise exception 'ADMIN ajeno hereda acceso'; end if;
 if public.list_trainer_technique_inbox(other)<>'[]'::jsonb then raise exception 'Bandeja técnica ajena'; end if;
 if public.list_trainer_exercise_videos()<>'[]'::jsonb then raise exception 'Lista reservas ajenas'; end if;
 begin perform public.get_exercise_video_asset(demo); raise exception 'ADMIN obtiene activo ajeno'; exception when insufficient_privilege then null; end;
 begin perform public.save_trainer_exercise(gen_random_uuid(),draft); raise exception 'Enlaza vídeo privado ajeno'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claim.sub',pupil::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 if not public.can_read_exercise_video(url) then raise exception 'Alumno no recibe demostración'; end if;
 execution:=public.start_scheduled_workout(scheduled);
 if not (public.get_client_technique_context(execution)->>'can_upload')::boolean then raise exception 'Sin contexto de subida propio'; end if;
 select id into set_id from public.workout_execution_sets where execution_id=execution limit 1;
 clip:=public.reserve_exercise_video_upload('client_technique',clip_op,42,'fixture.b-cdn.net',1000000,scheduled,execution,set_id);
 if public.reserve_exercise_video_upload('client_technique',clip_op,42,'fixture.b-cdn.net',1000000,scheduled,execution,set_id)<>clip then raise exception 'Duplica técnica'; end if;
 begin perform public.reserve_exercise_video_upload('client_technique',gen_random_uuid(),42,'fixture.b-cdn.net',1000000,scheduled,gen_random_uuid(),set_id); raise exception 'Asocia ejecución ajena'; exception when insufficient_privilege then null; end;
 reset role;
 perform public.claim_exercise_video_creation(clip,claim);
 perform public.complete_exercise_video_creation(clip,claim,clip_video);
 clip_url:='https://fixture.b-cdn.net/'||clip_video||'/play_720p.mp4';
 update public.exercise_video_assets set status='ready',duration_seconds=90,playback_bytes=1000000,provider_storage_bytes=2000000 where id=clip;
 set local role authenticated;
 perform set_config('request.jwt.claim.sub',trainer::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal2')::text,true);
 if not public.can_read_exercise_video(clip_url) then raise exception 'Preparador no ve técnica'; end if;
 if jsonb_array_length(public.list_trainer_technique_inbox(trainer))<>1
  or public.list_trainer_technique_inbox(trainer)->0->>'id'<>clip::text
  or public.list_trainer_technique_inbox(trainer)->0->>'assignment_id'<>scheduled::text
  or public.list_trainer_technique_inbox(trainer)->0 ? 'playback_url'
 then raise exception 'Bandeja técnica incompleta o expone URL'; end if;
 begin perform public.list_trainer_technique_inbox(other); raise exception 'Consulta bandeja de otra cuenta'; exception when insufficient_privilege then null; end;
 begin perform public.list_trainer_technique_inbox(trainer,now(),null); raise exception 'Cursor parcial'; exception when invalid_parameter_value then null; end;
 if public.list_trainer_technique_inbox(trainer,(public.list_trainer_technique_inbox(trainer)->0->>'created_at')::timestamptz,clip)<>'[]'::jsonb then raise exception 'Repite límite del cursor'; end if;
 perform set_config('request.jwt.claim.sub',other::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other,'role','authenticated','aal','aal2')::text,true);
 if public.list_trainer_technique_inbox(other)<>'[]'::jsonb then raise exception 'Bandeja técnica filtra mal al dueño'; end if;
 perform set_config('request.jwt.claim.sub',trainer::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal1')::text,true);
 begin perform public.list_trainer_technique_inbox(trainer); raise exception 'Bandeja técnica sin MFA'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal2')::text,true);
 reset role;
 update public.exercise_video_assets set shared=false where id=clip;
 set local role authenticated;
 if public.list_trainer_technique_inbox(trainer)<>'[]'::jsonb then raise exception 'Bandeja conserva clip sin consentimiento'; end if;
 reset role;
 update public.exercise_video_assets set shared=true where id=clip;
 set local role authenticated;

 if public.add_trainer_video_feedback(feedback,clip,12.5,'Mantén el control')<>feedback or public.add_trainer_video_feedback(feedback,clip,12.5,'Mantén el control')<>feedback then raise exception 'Duplica respuesta'; end if;
 if public.list_trainer_technique_inbox(trainer)<>'[]'::jsonb then raise exception 'Conserva vídeo ya corregido como pendiente'; end if;
 begin perform public.add_trainer_video_feedback(gen_random_uuid(),clip,91,'Fuera de tiempo'); raise exception 'Comentario fuera del clip'; exception when invalid_parameter_value then null; end;
 begin perform public.add_trainer_video_feedback(feedback,null,12.5,'Mantén el control'); raise exception 'Reintento cambia clip por NULL'; exception when invalid_parameter_value then null; end;
 reset role;
 update trainer_private.video_limits set feedback_limit=1 where trainer_id=trainer and scope='client_technique';
 set local role authenticated;
 begin perform public.add_trainer_video_feedback(gen_random_uuid(),clip,1,'Supera comentarios'); raise exception 'Supera cuota de comentarios'; exception when program_limit_exceeded then null; end;
 reset role;
 update trainer_private.video_limits set feedback_limit=100 where trainer_id=trainer and scope='client_technique';
 update public.trainer_access set enabled=false where trainer_id=trainer;
 set local role authenticated;
 begin perform public.add_trainer_video_feedback(gen_random_uuid(),clip,1,'Sin acceso'); raise exception 'Comenta sin acceso profesional'; exception when insufficient_privilege then null; end;
 if public.add_trainer_video_feedback(feedback,clip,12.5,'Mantén el control')<>feedback then raise exception 'Pierde recibo con acceso retirado'; end if;
 reset role;
 update public.trainer_access set enabled=true where trainer_id=trainer;
 set local role authenticated;
 perform public.end_trainer_relation(rel);
 if not public.can_read_exercise_video(clip_url) then raise exception 'Pierde historial del servicio'; end if;
 if public.add_trainer_video_feedback(feedback,clip,12.5,'Mantén el control')<>feedback then raise exception 'Pierde recibo después de baja'; end if;
 begin perform public.add_trainer_video_feedback(gen_random_uuid(),clip,1,'Tras baja'); raise exception 'Comenta después de baja'; exception when insufficient_privilege then null; end;
 if (public.list_client_technique_videos(scheduled)->0->>'can_feedback')::boolean then raise exception 'UI indica permiso de respuesta tras baja'; end if;
 perform set_config('request.jwt.claim.sub',pupil::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 if (public.get_client_technique_context(execution)->>'can_upload')::boolean then raise exception 'Contexto permite subir tras baja'; end if;
 perform public.set_client_technique_shared(share_op,clip,false);
 perform public.set_client_technique_shared(share_op,clip,false);
 if not public.can_read_exercise_video(clip_url) then raise exception 'Retirada oculta clip al dueño'; end if;
 begin perform public.reserve_exercise_video_upload('client_technique',gen_random_uuid(),42,'fixture.b-cdn.net',1000000,scheduled,execution,set_id); raise exception 'Sube después de baja'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claim.sub',trainer::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal2')::text,true);
 if public.can_read_exercise_video(clip_url) or jsonb_array_length(public.list_client_technique_videos(scheduled))<>0 then raise exception 'Retirada no corta acceso'; end if;
 begin perform public.add_trainer_video_feedback(gen_random_uuid(),clip,1,'Retirado'); raise exception 'Responde vídeo retirado'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claim.sub',pupil::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 perform public.set_client_technique_shared(gen_random_uuid(),clip,true);
 perform set_config('request.jwt.claim.sub',trainer::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal1')::text,true);
 if public.can_read_exercise_video(url) or public.can_read_exercise_video(clip_url) then raise exception 'Preparador lee sin MFA'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal2')::text,true);
 reset role;
 update trainer_private.video_limits set asset_limit=1 where trainer_id=trainer and scope='trainer_exercise';
 set local role authenticated;
 begin perform public.reserve_exercise_video_upload('trainer_exercise',gen_random_uuid(),42,'fixture.b-cdn.net',100); raise exception 'Supera cuota de activos'; exception when program_limit_exceeded then null; end;
 reset role;
 update trainer_private.video_limits set asset_limit=100,byte_limit=104857600 where trainer_id=trainer and scope='trainer_exercise';
 set local role authenticated;
 begin perform public.reserve_exercise_video_upload('trainer_exercise',gen_random_uuid(),42,'fixture.b-cdn.net',1); raise exception 'Supera presupuesto'; exception when program_limit_exceeded then null; end;
 reset role;
end $$;
select 'trainer_private_videos: OK' as result;
rollback;
